def even_odd_count(num):
    evens = 0
    odds = 0
    num = abs(num)  # Consider absolute value to ignore the sign

    for digit in str(num):
        if int(digit) % 2 == 0:
            evens += 1
        else:
            odds += 1

    return (evens, odds)

